-- =====================================================================
-- 2026_11_05_0007 — one invoice per clinic per billing period
--
-- Monthly invoicing is now generated by a job (tools/invoices.php) rather
-- than seeded by hand, and a job can run twice: a retried cron entry, two
-- operators, a clock that fires the same window again. The guard belongs in
-- the database, not in a check-then-insert in application code, because the
-- application check has a gap between the read and the write that two
-- processes can both fit through.
--
-- The index is partial on status so a cancelled invoice can be re-issued for
-- the same period. Cancelling an invoice and raising a corrected one is a
-- real billing workflow; double-billing is not.
-- =====================================================================

CREATE UNIQUE INDEX IF NOT EXISTS uq_invoice_period
    ON invoices (clinic_id, period_from)
    WHERE status NOT IN ('cancelled', 'void');
